private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate,Node start,Node stop,int dir){
    if (predicate == null) throw new IllegalArgumentException("Predicate must not be null");
    if (start == null || stop == null) throw new IllegalArgumentException("Start and stop nodes must not be null");
    if (start == stop) return new OuterFaceCirculator(start);

    java.util.Set<Node> visited = new java.util.HashSet<>();
    Node current = start;
    while (true) {
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }
        if (current == stop) {
            return new OuterFaceCirculator(stop);
        }
        visited.add(current);
        Node next = null;
        try {
            next = current.getNextOnOuterFace(dir);
        } catch (Exception e) {
            // Degraded traversal; return stop as fallback
            return new OuterFaceCirculator(stop);
        }
        if (next == null) {
            return new OuterFaceCirculator(stop);
        }
        if (visited.contains(next)) {
            // Loop detected without encountering stop
            return new OuterFaceCirculator(stop);
        }
        current = next;
    }
