public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    // Find the last path separator (both '/' and '\')
    int lastSlash = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    // Find the last dot
    int lastDot = path.lastIndexOf('.');
    // If there's no dot or the dot is before the last separator, no extension
    if (lastDot == -1 || lastDot <= lastSlash) {
        return null;
    }
    // If the dot is the very first character and there's no preceding path separator,
    // treat it as no extension (e.g., ".bashrc" or "foo.")
    if (lastSlash == -1 && lastDot == 0) {
        return null;
    }
    // If the dot is the last character (e.g., "file."), treat as no extension
    if (lastDot == path.length() - 1) {
        return null;
    }
    return path.substring(0, lastDot);
