    if (pane.getViewport().getView() != table) {
        throw new IllegalArgumentException("The provided JTable is not a child of the specified JScrollPane.");
    }
    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        // Out of bounds: ignore or clamp? We'll simply do nothing.
        return;
