private List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> bounds = new ArrayList<>();
    if (keys == null) {
        return bounds;
    }
    // Collect all integer keys into a set for quick lookup
    Set<Integer> keySet = new HashSet<>();
    for (K item : keys) {
        if (!(item instanceof Integer)) {
            throw new IllegalArgumentException("All keys must be of type Integer");
        }
        keySet.add((Integer) item);
    }
    // For each key compute the minimal outer integer greater than it
    for (K item : keys) {
        int key = (Integer) item;
        if (key == Integer.MAX_VALUE) {
            throw new IllegalArgumentException("Cannot compute upper bound for Integer.MAX_VALUE");
        }
        int candidate = key + 1;
        // Skip over any values that already appear in the key list
        while (keySet.contains(candidate)) {
            candidate++;
            if (candidate == Integer.MAX_VALUE) {
                throw new IllegalArgumentException("Overflow while computing upper bound");
            }
        }
        bounds.add(candidate);
    }
    return bounds;
