public boolean isExpired(long timestamp, long expiredThreshold) {
    // Treat non-positive thresholds as immediately expired
    if (expiredThreshold <= 0) {
        return true;
    }
    try {
        long now = System.currentTimeMillis();

        // If the timestamp is set in the future, it cannot be expired yet
        if (timestamp > now) {
            return false;
        }

        long diff = now - timestamp;
        return diff > expiredThreshold;
    } catch (Exception e) {
        // Any unexpected error results in a conservative expired flag
        return true;
    }
