    // Remove any writer that throws an IOException to keep the list clean.
    Iterator<Writer> it = writers.iterator();
    while (it.hasNext()) {
        Writer writer = it.next();
        if (writer == null) {
            it.remove();
            continue;
        }
        try {
            writer.write(message);
            writer.flush();
        } catch (IOException io) {
            // The writer is no longer valid; remove it from the list.
            it.remove();
